Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
const int MOD_CONST = 1000000007;
int p, k;

int compute_power(int base, int exp)
{
    if (exp == 1) return base;
    int half = compute_power(base, exp / 2);
    long long val = (1LL * half * half) % MOD_CONST;
    if (exp % 2 == 0) return (int)val;
    return (int)((val * base) % MOD_CONST);
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    cin >> p >> k;

    if (k == 0)
    {
        cout << compute_power(p, p - 1);
        return 0;
    }

    if (k == 1)
    {
        cout << compute_power(p, p);
        return 0;
    }

    int m_count = 1;
    int t = k;
    while (true)
    {
        m_count++;
        t = (1LL * t * k) % p;
        if (t == 1)
        {
            cout << compute_power(p, (p - 1) / m_count);
            return 0;
        }
    }

    return 0;
}
</original_code>
